import { motion, useReducedMotion } from "framer-motion";

export default function Contact() {
  const shouldReduceMotion = useReducedMotion();

  const fadeInVariants = {
    hidden: { opacity: 0, y: 40 },
    visible: { opacity: 1, y: 0 },
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const formData = new FormData(e.target);

    try {
      const response = await fetch("https://abrecruiters.com/submit.php", {
        method: "POST",
        body: formData,
      });

      if (response.ok) {
        alert("Form submitted successfully");
      } else {
        alert("Failed to submit form");
      }
    } catch (error) {
      console.error("Error:", error);
      alert("An error occurred");
    }
  };

  return (
    <section
      id="contact"
      className="min-h-screen py-8 sm:py-20 px-4 sm:px-8 flex flex-col justify-center items-center bg-gradient-to-br from-white/80 via-blue-50 to-pink-50 dark:from-gray-900 dark:via-blue-950 dark:to-purple-950 transition-colors duration-500"
    >
      <div className="container mx-auto">
        <motion.div
          className="max-w-2xl mx-auto w-full text-center glass p-6 sm:p-10 rounded-2xl shadow-2xl border border-white/20 flex flex-col justify-center items-center h-full"
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true }}
          variants={fadeInVariants}
          transition={{ duration: shouldReduceMotion ? 0 : 0.7 }}
        >
          <h2 className="text-3xl xs:text-4xl sm:text-5xl font-extrabold mb-6 sm:mb-8 gradient-text drop-shadow-lg">
            Contact Us
          </h2>

          {/* Contact Information */}
          <address className="not-italic space-y-4 sm:space-y-6 mb-8 w-full text-gray-700 dark:text-gray-200 text-center px-2">
            <motion.p whileHover={{ scale: shouldReduceMotion ? 1 : 1.02 }}>
              Phone:{" "}
              <a
                href="tel:+919650390840"
                className="text-blue-600 underline hover:text-pink-500 font-semibold transition-colors duration-200 focus:outline-none focus:ring-2 focus:ring-pink-500 rounded"
              >
                +91-9650390840
              </a>
            </motion.p>
            <motion.p whileHover={{ scale: shouldReduceMotion ? 1 : 1.02 }}>
              Email:{" "}
              <a
                href="mailto:info@abrecruiters.com"
                className="text-blue-600 underline hover:text-pink-500 transition-colors duration-200 focus:outline-none focus:ring-2 focus:ring-pink-500 rounded"
              >
                info@abrecruiters.com
              </a>{" "}
              /{" "}
              <a
                href="mailto:hr.abrecruiters@gmail.com"
                className="text-blue-600 underline hover:text-pink-500 transition-colors duration-200 focus:outline-none focus:ring-2 focus:ring-pink-500 rounded"
              >
                hr.abrecruiters@gmail.com
              </a>
            </motion.p>
            <motion.div whileHover={{ scale: shouldReduceMotion ? 1 : 1.02 }}>
              <p className="font-semibold mb-1">Reg. Office Address:</p>
              <p className="text-sm sm:text-base">
                85/5, Naresh Kumar, Bala School, Near Yashpal medical store,
                Mohalla Chouthiya, Kondal, Palwal, Haryana - 121103
              </p>
              <p className="text-sm sm:text-base mt-2">
                GST No.: 06DDSPP3304J1Z9
              </p>
              <p className="text-sm sm:text-base mt-2">
                UDYAM No.: UDYAM-HR-20-0031095
              </p>
            </motion.div>
          </address>

          {/* Contact Form */}
          <form
            className="mt-6 sm:mt-8 w-full flex flex-col gap-4"
            aria-label="Contact form"
            onSubmit={handleSubmit}
          >
            <input
              type="text"
              name="name"
              placeholder="Your Name"
              aria-label="Your Name"
              className="bg-white/90 dark:bg-gray-800 px-4 py-3 rounded-lg border border-blue-200 focus:outline-none focus:ring-2 focus:ring-blue-400 text-gray-900 dark:text-gray-100 text-sm sm:text-base transition-all duration-200 placeholder-gray-500"
              required
            />
            <input
              type="email"
              name="email"
              placeholder="Your Email"
              aria-label="Your Email"
              className="bg-white/90 dark:bg-gray-800 px-4 py-3 rounded-lg border border-blue-200 focus:outline-none focus:ring-2 focus:ring-blue-400 text-gray-900 dark:text-gray-100 text-sm sm:text-base transition-all duration-200 placeholder-gray-500"
              required
            />

            <input
              type="text"
              name="mobile"
              placeholder="Mobile No."
              aria-label="Mobile No."
              className="bg-white/90 dark:bg-gray-800 px-4 py-3 rounded-lg border border-blue-200 focus:outline-none focus:ring-2 focus:ring-blue-400 text-gray-900 dark:text-gray-100 text-sm sm:text-base transition-all duration-200 placeholder-gray-500"
              required
            />
            <textarea
              name="message"
              placeholder="Your Message"
              aria-label="Your Message"
              className="bg-white/90 dark:bg-gray-800 px-4 py-3 rounded-lg border border-blue-200 focus:outline-none focus:ring-2 focus:ring-blue-400 text-gray-900 dark:text-gray-100 text-sm sm:text-base resize-none placeholder-gray-500"
              rows={4}
              required
            ></textarea>
            <motion.button
              type="submit"
              className="bg-gradient-to-r from-blue-500 to-pink-500 text-white px-5 sm:px-7 py-3 rounded-full font-semibold shadow-lg hover:scale-105 focus:scale-105 transition-all duration-200 focus:outline-none focus:ring-4 focus:ring-pink-400"
              whileHover={shouldReduceMotion ? {} : { scale: 1.05 }}
              whileTap={shouldReduceMotion ? {} : { scale: 0.98 }}
            >
              Send Message
            </motion.button>
          </form>

          <div className="mt-8 flex justify-center gap-6">
            <a
              href="mailto:info@abrecruiters.com"
              className="text-blue-600 hover:text-pink-500 font-bold text-sm sm:text-base transition-colors duration-200"
            >
              Email
            </a>
            <a
              href="tel:+919650390840"
              className="text-blue-600 hover:text-pink-500 font-bold text-sm sm:text-base transition-colors duration-200"
            >
              Call
            </a>
          </div>
        </motion.div>
      </div>
    </section>
  );
}
